pub(crate) use claude_launch::claude_launch;
pub(crate) use claude_model_flag::claude_model_flag;
pub(crate) use claude_project_dir_name::claude_project_dir_name;
pub(crate) use claude_project_transcripts_dir::claude_project_transcripts_dir;
pub(crate) use bsc_agent_session_path::bsc_agent_session_path;
pub(crate) use caged_agent_conversation_dir::caged_agent_conversation_dir;
pub(crate) use caged_agent_conversation_path::caged_agent_conversation_path;
pub(crate) use caged_claude_transcripts_dir::caged_claude_transcripts_dir;

use crate::prelude::*;

/// Whether Claude has a prior conversation for `cwd`. `--continue` aborts with
/// "No conversation found to continue" (and never delivers the baked startup
/// prompt) when there's no history, so we only pass the flag when this is true.
/// Fail-safe: any uncertainty (empty cwd, unreadable dir) returns `false`, which
/// launches a fresh session so the prompt is always delivered.
pub(crate) fn has_claude_history(cwd: &str) -> bool {
    if cwd.is_empty() {
        return false;
    }
    dir_holds_a_transcript(&claude_project_transcripts_dir(cwd))
}

/// Whether `dir` is a Claude Code transcripts directory holding at least one conversation.
///
/// Split out because a SANDBOXED session's transcripts are not at the path
/// [`claude_project_transcripts_dir`] computes: the caged harness writes into its private HOME under
/// the GUEST cwd, and the launcher binds that directory to a per-pane host dir. The rule for "is there
/// something to continue" is the same either way — a `.jsonl` in the directory — so it lives here once
/// and both callers ask it about their own path.
pub(crate) fn dir_holds_a_transcript(dir: &std::path::Path) -> bool {
    let Ok(entries) = std::fs::read_dir(dir) else { return false };
    entries
        .flatten()
        .any(|e| e.path().extension().and_then(|x| x.to_str()) == Some("jsonl"))
}

/// Where a caged `bsc-agent` keeps its conversation, inside the guest.
///
/// Under the private HOME rather than `/repo`: the worktree is the session's WORK, and a conversation
/// file committed by accident is the failure `SandboxSpec::home` was split out to prevent. The
/// directory is bound read-write and persists across launches, which is what makes `--continue` mean
/// anything for a caged worker — without it the per-step save from
/// `a-local-agent-turn-is-invisible-while-it-runs-and-lost-if-it-dies` writes to a tmpfs that dies
/// with the session.
///
/// It lives HERE, beside the host path it is the caged twin of, because the launcher binds it and the
/// resume probe reads it and those two agreeing is the whole correctness condition — see
/// [`caged_agent_conversation_dir`].
pub(crate) const CAGED_AGENT_SESSION_GUEST: &str = bsc_session::CAGED_AGENT_SESSION_GUEST;

/// Whether a `bsc-agent` conversation file holds something worth resuming — it exists and is
/// non-empty.
///
/// The counterpart of [`dir_holds_a_transcript`] for the other harness: Claude's history is a
/// DIRECTORY of `.jsonl` transcripts, `bsc-agent`'s is a single JSON FILE, so "is there anything to
/// continue" is a different question and each harness answers it about its own path.
pub(crate) fn file_holds_a_conversation(path: &std::path::Path) -> bool {
    std::fs::metadata(path).map(|m| m.len() > 0).unwrap_or(false)
}

/// Whether `bsc-agent` has a resumable conversation for `cwd` — a non-empty session file exists.
/// Fail-safe: any uncertainty returns `false`, launching a fresh session. (#1144)
pub(crate) fn has_bsc_agent_history(cwd: &str) -> bool {
    bsc_agent_session_path(cwd)
        .and_then(|p| std::fs::metadata(p).ok())
        .map(|m| m.len() > 0)
        .unwrap_or(false)
}

