    #![allow(unused_imports)]
    use super::*;
    use crate::testutil::prelude::*;

    #[test]
    fn claude_launch_references_the_prompt_fresh() {
        // REFERENCED, not inlined — see `claude_launch`. The pty truncates a long line and a cut
        // `$'…'` leaves the quote open, so the agent never starts.
        assert_eq!(claude_launch("triage the issues", false, None), "claude \"$BSC_STARTUP_PROMPT\"");
        assert!(!claude_launch("triage the issues", false, None).contains("triage"));
    }

    /// A RESUME NAMES ITS SESSION. `--continue` resumes "the newest transcript in this directory" by
    /// mtime, which is not the same question as "the conversation this pane was having" — measured on
    /// a live architect, a 24KB conversation sat unreachable beside a 3KB metadata-only stub that
    /// happened to be newer.
    #[test]
    fn claude_launch_resumes_by_session_id_rather_than_by_recency() {
        let id = "bf36a25c-b331-48b0-a78c-3bf4e6b51354";
        let cmd = claude_launch("triage the issues", true, Some(id));
        assert!(cmd.contains("--resume"), "{cmd}");
        assert!(cmd.contains(id), "the id travels: {cmd}");
        assert!(!cmd.contains("--continue"), "and recency is not consulted: {cmd}");
        // The flag precedes the prompt REFERENCE, or claude reads the id as the prompt.
        assert!(cmd.find("--resume").unwrap() < cmd.find("$BSC_STARTUP_PROMPT").unwrap(), "{cmd}");
    }

    /// The id lands on a command line, so it is quoted at the point of interpolation — local to the
    /// line that needs the guarantee, rather than resting on a check somewhere upstream.
    #[test]
    fn a_session_id_is_quoted_into_the_command() {
        let cmd = claude_launch("go", true, Some("bf36a25c-b331-48b0-a78c-3bf4e6b51354"));
        assert!(cmd.contains("$'bf36a25c-b331-48b0-a78c-3bf4e6b51354'"), "{cmd}");
    }
    #[test]
    fn claude_project_dir_name_replaces_non_alnum_with_dash() {
        // Matches the dir Claude Code creates under ~/.claude/projects.
        assert_eq!(
            claude_project_dir_name(r"C:\Users\Kevin\Projects\rust\base-studio-code"),
            "C--Users-Kevin-Projects-rust-base-studio-code"
        );
        // Consecutive specials (\ then .) each map to their own dash.
        assert_eq!(
            claude_project_dir_name(r"C:\Users\Kevin\.base-studio-code\documents"),
            "C--Users-Kevin--base-studio-code-documents"
        );
    }
    #[test]
