use crate::prelude::*;

/// Build the shell command that launches `claude` with the baked startup prompt.
///
/// `resume` is the session to reattach to — `Some(id)` emits `--resume <id>`, `None` starts fresh.
///
/// # Why an ID and not `--continue`
///
/// `--continue` resumes "the most recent conversation in this directory" by mtime, which is a
/// different question from "the conversation this pane was having". A metadata-only transcript (a
/// cancelled `/resume`, a launch that died before its first turn) becomes the newest file and shadows
/// the real thread permanently — measured on a live architect, whose 24KB conversation sat unreachable
/// beside a 3KB stub. Naming the session removes the guess.
///
/// The id comes from Claude's own `lastSessionId` (see [`crate::session::claude_config::last_session_id`]),
/// so it follows a `/clear` rather than resurrecting cleared context.
pub(crate) fn claude_launch(prompt: &str, resume: bool, resume_id: Option<&str>) -> String {
    let flag = match (resume, resume_id) {
        // The id is shell-quoted even though it is shape-checked upstream: quoting at the point of
        // interpolation is what makes the guarantee local to the line that needs it.
        (_, Some(id)) => format!("--resume {} ", bash_ansi_c_quote(id)),
        // RESUMING WITHOUT AN ID still resumes. `--resume` names one conversation; `--continue` takes
        // the newest for this directory, which is a worse resume than naming it and a far better one
        // than silently starting over — the outcome when this arm did not exist.
        (true, None) => "--continue ".to_string(),
        (false, None) => String::new(),
    };
    // THE PROMPT IS REFERENCED, NOT INLINED (`the-startup-prompt-outgrew-the-tty-line-limit`).
    //
    // This line is typed into an interactive shell through a pty, which silently DISCARDS everything
    // past 4096 bytes on one physical line. An inlined `$'…'` prompt that gets cut leaves the quote
    // open, so bash waits at its `>` continuation prompt and the agent never starts — no error, no
    // log, just a shell. `$BSC_STARTUP_PROMPT` is set by `pty_create` from the same value, so this
    // line is a constant few dozen bytes whatever the prompt's size.
    //
    // Double quotes rather than `$'…'`: the value is already a shell VARIABLE, so it needs no
    // escaping, and `"$VAR"` keeps its newlines inside one argument.
    let _ = prompt;
    format!("claude {}\"$BSC_STARTUP_PROMPT\"", flag)
}
/// Map a UI model id (`sonnet-4.5`, `opus-4.5`, `haiku-4.5`) to the alias Claude
/// Code's `--model` flag accepts. Returns `None` for anything unrecognized, so the
/// session falls back to Claude Code's own default and we never interpolate an
/// arbitrary caller string into the shell command (the table only ever yields a
/// fixed literal — no injection surface).
///
/// The table itself is [`bsc_util::MODEL_TIERS`], not a `match` here: the `bsc persona model` /
/// `bsc teams model` verbs VALIDATE against the same list, so a tier a session is allowed to write
/// is exactly a tier this launch can carry. It used to be a local match, which meant the CLIs had
/// nothing to check against and would have needed a copy of their own.
pub(crate) fn claude_model_flag(model: &str) -> Option<&'static str> {
    bsc_util::model_alias(model)
}
/// Claude Code's on-disk *directory name* for a launch cwd. Conversations live at
/// `~/.claude/projects/<dir>/<session>.jsonl`, where `<dir>` is the cwd with every
/// non-alphanumeric character replaced by `-`
/// (e.g. `C:\Users\Kevin\foo` → `C--Users-Kevin-foo`).
///
/// NOT to be confused with [`crate::session::claude_config::claude_project_key`] (`claude_config.rs`):
/// that produces the cwd's *key in the `projects` map of `~/.claude.json`* — a slash-normalised path
/// (`C:/Users/Kevin/foo`), a different transform for a different on-disk Claude Code contract. Both
/// names are frozen to match what Claude Code writes; do not "unify" them.
pub(crate) fn claude_project_dir_name(cwd: &str) -> String {
    // ONE definition, in `bsc-session`, because `bsc session reset` needs the same answer and cannot
    // reach a `pub(crate)` here. Semantics stay frozen; this is now a re-export in function form so
    // the nine existing call sites keep their name. (`map_slug` deliberately did NOT move — it has
    // other callers in `fsx.rs`, and only its RULE was needed here.)
    bsc_session::claude_project_dir_name(cwd)
}
/// Claude Code's on-disk *transcripts directory* for a launch cwd:
/// `~/.claude/projects/<claude_project_dir_name(cwd)>`, where each conversation is stored as a
/// `<session>.jsonl`. The one construction of this path, shared by [`has_claude_history`] and
/// [`crate::fleet::inspect::claude_transcript_path`]. Pure path assembly — callers keep their own
/// empty-cwd guard (both bail before reading when `cwd` is blank).
pub(crate) fn claude_project_transcripts_dir(cwd: &str) -> std::path::PathBuf {
    home_dir().join(".claude").join("projects").join(claude_project_dir_name(cwd))
}
/// Whether Claude has a prior conversation for `cwd`. `--continue` aborts with
/// "No conversation found to continue" (and never delivers the baked startup
/// prompt) when there's no history, so we only pass the flag when this is true.
/// Fail-safe: any uncertainty (empty cwd, unreadable dir) returns `false`, which
/// launches a fresh session so the prompt is always delivered.
pub(crate) fn has_claude_history(cwd: &str) -> bool {
    if cwd.is_empty() {
        return false;
    }
    dir_holds_a_transcript(&claude_project_transcripts_dir(cwd))
}

/// Whether `dir` is a Claude Code transcripts directory holding at least one conversation.
///
/// Split out because a SANDBOXED session's transcripts are not at the path
/// [`claude_project_transcripts_dir`] computes: the caged harness writes into its private HOME under
/// the GUEST cwd, and the launcher binds that directory to a per-pane host dir. The rule for "is there
/// something to continue" is the same either way — a `.jsonl` in the directory — so it lives here once
